import json
import re
from docx import Document

def fill_offer_letter():
    # Load data
    with open('/root/employee_data.json', 'r') as f:
        data = json.load(f)

    # Load template
    doc = Document('/root/offer_letter_template.docx')

    def process_paragraph(para):
        text = para.text

        # 1. Handle Relocation Conditional
        # The inspection showed it's in a single paragraph:
        # {{IF_RELOCATION}}...{{END_IF_RELOCATION}}
        if '{{IF_RELOCATION}}' in text and '{{END_IF_RELOCATION}}' in text:
            if data.get('RELOCATION_PACKAGE') == 'Yes':
                # Remove markers, keep content
                text = text.replace('{{IF_RELOCATION}}', '').replace('{{END_IF_RELOCATION}}', '')
            else:
                # Remove everything
                # Regex to match everything between markers including newlines if any
                # But simple string replacement works if we assume it's the whole text or distinct part
                # text = re.sub(r'\{\{IF_RELOCATION\}\}.*?\{\{END_IF_RELOCATION\}\}', '', text)
                # Since we saw it covers the whole paragraph text in the inspection, we can just empty it
                text = ""

        # 2. Replace Placeholders
        # Find all {{KEY}} patterns
        pattern = r'\{\{([A-Z_]+)\}\}'
        if re.search(pattern, text):
            matches = re.finditer(pattern, text)
            for match in matches:
                key = match.group(1)
                placeholder = match.group(0)
                if key in data:
                    text = text.replace(placeholder, str(data[key]))

        # 3. Update Paragraph if changed
        # We check against original text (re-reading para.text to be safe, though 'text' var holds our modified version)
        if text != para.text:
            if para.runs:
                para.runs[0].text = text
                for run in para.runs[1:]:
                    run.text = ''
            else:
                # If no runs exist but we have text (unlikely in docx unless created empty), add one
                if text:
                    para.add_run(text)

    # Process all parts of the document

    # Body Paragraphs
    for para in doc.paragraphs:
        process_paragraph(para)

    # Tables (and nested tables)
    def process_table(table):
        for row in table.rows:
            for cell in row.cells:
                for para in cell.paragraphs:
                    process_paragraph(para)
                for nested_table in cell.tables:
                    process_table(nested_table)

    for table in doc.tables:
        process_table(table)

    # Sections (Headers/Footers)
    for section in doc.sections:
        if section.header:
            for para in section.header.paragraphs:
                process_paragraph(para)
            for table in section.header.tables:
                process_table(table)
        if section.footer:
            for para in section.footer.paragraphs:
                process_paragraph(para)
            for table in section.footer.tables:
                process_table(table)

    # Save result
    doc.save('/root/offer_letter_filled.docx')
    print("Successfully generated /root/offer_letter_filled.docx")

if __name__ == "__main__":
    fill_offer_letter()

